-- PearlHub seed: technology articles (t1 - t7).
insert into public.articles (id, title, slug, excerpt, content, category, subcategory, author_id, published_at, read_time, tags, featured, gradient) values
('t1', 'Top 10 AI Tools Every Student in Nigeria Should Use in 2025', 'top-ai-tools-nigeria-2025',
 'From research assistants to writing tools, these AI platforms are transforming how Nigerian students learn, write, and build projects.',
 $j$[{"type":"paragraph","content":"Artificial intelligence is no longer a luxury reserved for big tech companies. Across Nigeria, students are using AI-powered tools to write better essays, debug code faster, and research more efficiently than ever before."},{"type":"heading","content":"1. Research & Summarization Tools"},{"type":"paragraph","content":"Tools like Perplexity AI and Elicit help students find academic sources and summarize complex papers in seconds. For Nigerian university students working on final year projects, these tools save hours of manual literature review."},{"type":"callout","content":"Pro tip: Use Elicit to find peer-reviewed papers on any topic. It searches over 100 million academic papers and extracts key findings automatically."},{"type":"heading","content":"2. Writing & Editing Assistants"},{"type":"paragraph","content":"Grammarly, QuillBot, and Jasper AI help students polish their academic writing. QuillBot paraphrasing tool is especially useful for rewording research notes without losing meaning."},{"type":"heading","content":"3. Coding & Development Helpers"},{"type":"paragraph","content":"GitHub Copilot and Cursor AI are game-changers for programming students. They autocomplete code, explain errors, and even generate entire functions from natural language descriptions."},{"type":"list","content":"Most popular AI tools among Nigerian students:","items":["ChatGPT for brainstorming and explanations","Perplexity for academic research","QuillBot for paraphrasing essays","GitHub Copilot for coding assignments","Canva AI for presentation design"]},{"type":"paragraph","content":"The key is using these tools as learning aids, not shortcuts. Students who understand how to prompt effectively get far better results than those who simply copy outputs."}]$j$::jsonb,
 'technology', 'Artificial Intelligence', 'a1', '2025-01-15', 8, array['AI','Tools','Students','Nigeria'], true, 'from-indigo-600 to-purple-600'),
('t2', 'Python for Beginners: A Complete Roadmap for African Developers', 'python-beginners-roadmap-africa',
 'A structured learning path from zero to job-ready Python developer, tailored for the African tech ecosystem and remote work market.',
 $j$[{"type":"paragraph","content":"Python remains the most beginner-friendly programming language with the widest range of career paths. From data science to web development, Python opens doors across the African tech industry."},{"type":"heading","content":"Phase 1: Foundations (Weeks 1-4)"},{"type":"paragraph","content":"Start with variables, data types, loops, and functions. Practice on platforms like HackerRank and LeetCode. Build small projects: a calculator, a to-do list, a number guessing game."},{"type":"code","content":"def greet(name: str) -> str:
    return f"Hello, {name}! Welcome to Python."

print(greet("Lagos"))"},{"type":"heading","content":"Phase 2: Intermediate (Weeks 5-10)"},{"type":"paragraph","content":"Learn object-oriented programming, file handling, error handling, and working with APIs. Build a weather app using a REST API or a web scraper for Nigerian news sites."},{"type":"heading","content":"Phase 3: Specialization (Weeks 11-20)"},{"type":"list","content":"Choose your path:","items":["Web Development: Django or Flask for building APIs","Data Science: Pandas, NumPy, and Matplotlib","Machine Learning: scikit-learn and TensorFlow","Automation: Selenium, BeautifulSoup, and cron jobs"]},{"type":"paragraph","content":"The African tech market values developers who can build real products. Focus on portfolio projects that solve local problems: fintech tools, agricultural data apps, or education platforms."}]$j$::jsonb,
 'technology', 'Python Programming', 'a3', '2025-01-10', 12, array['Python','Programming','Roadmap','Beginners'], true, 'from-blue-600 to-cyan-500'),
('t3', 'React vs Next.js: Which Framework Should You Learn First?', 'react-vs-nextjs-2025',
 'A practical comparison of React and Next.js for developers deciding their first modern JavaScript framework.',
 $j$[{"type":"paragraph","content":"This is one of the most common questions from developers in our community. Both React and Next.js are excellent, but they serve different purposes and learning them in the right order matters."},{"type":"heading","content":"Understanding the Relationship"},{"type":"paragraph","content":"Next.js is built on top of React. Learning React first gives you a stronger foundation. Next.js adds routing, server-side rendering, and API routes on top of React component model."},{"type":"heading","content":"When to Choose React"},{"type":"list","content":["Building single-page applications (SPAs)","Working with existing backend APIs","Learning component-based UI thinking","Building mobile apps with React Native"]},{"type":"heading","content":"When to Choose Next.js"},{"type":"list","content":["Building SEO-friendly websites","Creating full-stack applications","Need server-side rendering or static generation","Building content-heavy sites like blogs or e-commerce"]},{"type":"callout","content":"Our recommendation: Spend 4-6 weeks learning React fundamentals, then transition to Next.js for real projects. This gives you the best of both worlds."}]$j$::jsonb,
 'technology', 'React & Next.js', 'a3', '2025-01-08', 7, array['React','Next.js','JavaScript','Web Dev'], false, 'from-violet-600 to-fuchsia-500'),
('t4', 'Best Budget Laptops Under 300,000 Naira for Programming in 2025', 'budget-laptops-under-300k-nigeria',
 'Real-world tested laptops that can handle coding, virtual machines, and development tools without breaking the bank.',
 $j$[{"type":"paragraph","content":"Finding a reliable programming laptop in Nigeria under 300,000 Naira is challenging but possible. We tested 12 models over three months running VS Code, Docker, and browser-heavy development workflows."},{"type":"heading","content":"Top Pick: Lenovo ThinkPad E14 Gen 5"},{"type":"paragraph","content":"With an AMD Ryzen 5 7530U, 16GB RAM, and 512GB SSD, this machine handles full-stack development comfortably. The keyboard is exceptional for long coding sessions, and the build quality is military-grade."},{"type":"heading","content":"Runner Up: HP Pavilion 15 (2024)"},{"type":"paragraph","content":"Intel Core i5-1335U with 12GB RAM. Slightly less powerful than the ThinkPad but offers a better display and more ports. Great for students who also need a laptop for presentations and media."},{"type":"list","content":"Key specs to look for:","items":["Minimum 8GB RAM (16GB strongly recommended)","SSD storage (avoid HDDs entirely)","Multi-core processor (Ryzen 5 or Intel i5 minimum)","Full HD display for comfortable coding","Good keyboard for long typing sessions"]}]$j$::jsonb,
 'technology', 'Gadgets/Tech News', 'a5', '2025-01-05', 6, array['Laptops','Budget','Programming','Nigeria'], true, 'from-amber-500 to-orange-600'),
('t5', 'How to Build Your First Web App with HTML, CSS, and JavaScript', 'first-web-app-html-css-js',
 'A step-by-step tutorial to build a fully functional task manager web application from scratch using vanilla web technologies.',
 $j$[{"type":"paragraph","content":"Every web developer starts with HTML, CSS, and JavaScript. In this tutorial, we will build a task manager application that lets users add, complete, and delete tasks with local storage persistence."},{"type":"heading","content":"Step 1: Setting Up the Project"},{"type":"code","content":"<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>My Task Manager</title>
  <link rel="stylesheet" href="styles.css">
</head>
<body>
  <div id="app"></div>
  <script src="app.js"></script>
</body>
</html>"},{"type":"heading","content":"Step 2: Styling with CSS"},{"type":"paragraph","content":"Use CSS Grid and Flexbox for layout. Define custom properties for colors so your app supports dark mode easily. Keep your stylesheet organized with sections for layout, components, and utilities."},{"type":"heading","content":"Step 3: Adding Interactivity with JavaScript"},{"type":"paragraph","content":"Use DOM manipulation to handle user events. Store tasks in localStorage so data persists between sessions. Keep your code modular with separate functions for rendering, event handling, and data management."},{"type":"callout","content":"Challenge: After completing this tutorial, try adding features like task categories, due dates, or drag-and-drop reordering to deepen your skills."}]$j$::jsonb,
 'technology', 'HTML/CSS/JavaScript', 'a3', '2025-01-03', 15, array['HTML','CSS','JavaScript','Tutorial'], false, 'from-emerald-500 to-teal-600'),
('t6', 'Notion vs Obsidian: Best Note-Taking App for Students', 'notion-vs-obsidian-students',
 'An in-depth comparison of the two most popular note-taking tools, evaluated for academic use, offline access, and long-term knowledge management.',
 $j$[{"type":"paragraph","content":"Choosing the right note-taking app can dramatically improve your study efficiency. Notion and Obsidian represent two different philosophies: cloud-first collaboration versus local-first knowledge graphs."},{"type":"heading","content":"Notion: The All-in-One Workspace"},{"type":"paragraph","content":"Notion excels at structured notes, databases, and team collaboration. Its template gallery includes ready-made study planners, lecture note layouts, and assignment trackers."},{"type":"heading","content":"Obsidian: The Knowledge Graph"},{"type":"paragraph","content":"Obsidian stores notes as plain Markdown files on your device. The linking system creates a visual knowledge graph that reveals connections between topics you never expected."},{"type":"list","content":"Quick verdict:","items":["Choose Notion if you need collaboration, databases, and templates","Choose Obsidian if you want offline access, speed, and linked thinking","Students with unreliable internet should prefer Obsidian","Group project teams benefit more from Notion"]}]$j$::jsonb,
 'technology', 'Software Reviews', 'a1', '2024-12-28', 9, array['Notion','Obsidian','Productivity','Students'], false, 'from-slate-600 to-zinc-700'),
('t7', 'AI Tools & Tutorials: Automating Repetitive Tasks with Python Scripts', 'ai-automation-python-scripts',
 'Learn how to combine AI APIs with Python automation to eliminate hours of repetitive work, from data entry to report generation.',
 $j$[{"type":"paragraph","content":"Combining AI APIs with Python automation creates powerful workflows that save hours every week. This guide walks through three practical automation projects using free AI tools."},{"type":"heading","content":"Project 1: Auto-Generate Meeting Summaries"},{"type":"paragraph","content":"Use the Whisper API to transcribe meeting recordings, then pass the text to a summarization model. Output clean meeting notes saved directly to your project management tool."},{"type":"heading","content":"Project 2: Smart Email Categorizer"},{"type":"paragraph","content":"Build a script that reads your inbox, classifies emails by urgency and topic using a classification model, and creates labeled folders automatically."},{"type":"code","content":"import openai

response = openai.chat.completions.create(
    model="gpt-4o-mini",
    messages=[{"role": "user", "content": f"Classify this email: {email_body}"}]
)"},{"type":"paragraph","content":"These projects use free-tier API access and take under 50 lines of code each. Start with one, master it, then expand to more complex workflows."}]$j$::jsonb,
 'technology', 'AI Tools & Tutorials', 'a1', '2024-12-20', 11, array['AI','Python','Automation','Tutorial'], false, 'from-rose-500 to-pink-600')
